{"command": "cat > /app/scan_persistence.sh << 'SCRIPT_EOF'
#!/usr/bin/env bash
# scan_persistence.sh - idempotent scan of Linux persistence artifacts
set -u

REPORT="/app/persistence_report.json"
ARTS=()   # each entry: type|path|sha256|line_number|content_preview|user

# ---------- helpers ----------
json_escape() {
  # escape a string for JSON (backslash, quote, control chars)
  local s="$1"
  s="${s//\\/\\\\}"
  s="${s//\"/\\\"}"
  s="${s//$'\t'/\\t}"
  s="${s//$'\n'/\\n}"
  s="${s//$'\r'/\\r}"
  printf '%s' "$s"
}

first100() {
  printf '%s' "$1" | head -c 100
}

add_artifact() {
  # args: type path sha256 line_number content_preview user
  ARTS+=("$1|$2|$3|$4|$5|$6")
}

file_sha() {
  sha256sum "$1" 2>/dev/null | awk '{print $1}'
}

SCRIPT_EOF
echo "part1 written"; wc -l /app/scan_persistence.sh"}

